cd /tmp/claude-0/-home-user-ainews/917c6846-924a-5b67-97a0-b7110f40b43f/scratchpad && python3 -c "
import zlib,re
d=open('ie.pdf','rb').read()
streams=[]
for m in re.finditer(rb'stream\r?\n(.*?)endstream', d, re.S):
    try: streams.append(zlib.decompress(m.group(1)))
    except Exception: pass
cmap={}
for s in streams:
    if b'beginbfchar' in s or b'beginbfrange' in s:
        t=s.decode('latin-1')
        for blk in re.findall(r'beginbfchar(.*?)endbfchar', t, re.S):
            for a,b in re.findall(r'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', blk):
                cmap[int(a,16)]=''.join(chr(int(b[i:i+4],16)) for i in range(0,len(b),4))
        for blk in re.findall(r'beginbfrange(.*?)endbfrange', t, re.S):
            for lo,hi,dst in re.findall(r'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', blk):
                lo,hi=int(lo,16),int(hi,16); base=int(dst,16)
                for i in range(lo,hi+1): cmap[i]=chr(base+i-lo)
print('cmap size',len(cmap))
out=[]
pat=re.compile(r'\((\\\\.|[^()\\\\])*\)')
for s in streams:
    if b'beginbfchar' in s or b'beginbfrange' in s: continue
    t=s.decode('latin-1')
    if ' Tj' not in t and ' TJ' not in t: continue
    for m in pat.finditer(t):
        raw=m.group(0)[1:-1]
        out.append(''.join(cmap.get(ord(c), c) for c in raw))
txt=''.join(out)
open('ie.txt','w').write(txt)
print(len(txt)); print(repr(txt[:400]))
"

