const fs=require("fs"),p="data/2026-09-29.json";const d=JSON.parse(fs.readFileSync(p,"utf8"));
const drop=["Manus ships","Milestone oracles reveal","Across 74,944 samples","Traffic-analysis benchmark","Cerebras to supply","Shopify opens checkout","Consumer agent startup Instinct"];
let n=0;
for(const s of d.sections){s.items=s.items.filter(i=>{const k=drop.some(x=>i.headline.startsWith(x));if(k)n++;return !k;});}
d.sections=d.sections.filter(s=>s.items.length);
fs.writeFileSync(p,JSON.stringify(d,null,2)+"\n");
console.log("dropped",n,"remaining",d.sections.reduce((a,s)=>a+s.items.length,0));
console.log(d.sections.map(s=>s.name+":"+s.items.length).join(" | "));
'

